                  fill="#c2410c"
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey="mixShiftPp"
                  name="Mix-shift contribution"
                  fill="#0f766e"
                  radius={[4, 4, 0, 0]}
                />
                <Line
                  type="monotone"
                  dataKey="servicesRisePp"
                  name="Services PCE rise"
                  stroke="#64748b"
                  strokeWidth={2}
                />
              </ComposedChart>
            </ResponsiveContainer>
          )}
        </div>

        <p className="mt-3 text-[11px] leading-relaxed text-slate-400">
          {SOURCE_NOTE}
        </p>
      </div>
    </div>
  );
}

