                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                  domain={[20, 65]}
                />
                <YAxis
                  type="category"
                  dataKey="abbr"
                  width={36}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip formatter={tipPct} contentStyle={{ fontSize: 12 }} />
                <Bar dataKey="escaped" name="Escaped share" radius={[0, 4, 4, 0]}>
                  {ladderData.map((d) => (
                    <Cell key={d.abbr} fill={d.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}

          {panel === "rate-breadth" && (
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ left: 8, right: 16, top: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="services"
                  name="FTA services taxed"
                  tick={{ fontSize: 11 }}
                  domain={[0, 180]}
                  label={{
                    value: "FTA services taxed (of 176)",
                    position: "insideBottom",
                    offset: -2,
                    style: { fontSize: 11 },
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="rate"
                  name="Combined rate"
                  tick={{ fontSize: 11 }}
                  unit="%"
                  domain={[4, 10]}
                />
                <ZAxis type="number" dataKey="escaped" range={[60, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  contentStyle={{ fontSize: 12 }}
                  formatter={(value, name) => {
                    if (name === "Combined rate") return [`${value}%`, name];
                    if (name === "FTA services taxed") return [value, name];
                    return [value, name];
                  }}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.abbr ?? ""
                  }
                />
                <Scatter
                  name="GST states"
                  data={scatterData.filter((d) => !d.broad)}
                  fill="#c2410c"
                />
                <Scatter
                  name="Broad-base peers"
                  data={scatterData.filter((d) => d.broad)}
                  fill="#0f766e"
                />
                <Legend />
              </ScatterChart>
            </ResponsiveContainer>
          )}

          {panel === "service-leaks" && (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={[...SERVICE_CATEGORIES].sort(
                  (a, b) => b.leakScore - a.leakScore,
                )}
                layout="vertical"
                margin={{ left: 8, right: 16 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 11 }} />
                <YAxis
                  type="category"
                  dataKey="category"
                  width={150}
                  tick={{ fontSize: 10 }}
                />
                <Tooltip contentStyle={{ fontSize: 12 }} />
                <Bar dataKey="leakScore" name="Leak score" radius={[0, 4, 4, 0]}>
                  {SERVICE_CATEGORIES.map((c) => (
                    <Cell key={c.id} fill={c.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}

          {panel === "decade-deltas" && (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={DECADE_DELTAS}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="decade" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} tickFormatter={(v) => `${v} pp`} />
                <Tooltip contentStyle={{ fontSize: 12 }} />
                <Legend />
                <Bar
                  dataKey="escapeRisePp"
                  name="Escape rise"
                  fill="#c2410c"
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey="mixShiftPp"
                  name="Mix-shift contribution"
                  fill="#0f766e"
                  radius={[4, 4, 0, 0]}
                />
                <Line
                  type="monotone"
                  dataKey="servicesRisePp"
                  name="Services PCE rise"
                  stroke="#64748b"
                  strokeWidth={2}
                />
              </ComposedChart>
            </ResponsiveContainer>
          )}
        </div>

        <p className="mt-3 text-[11px] leading-relaxed text-slate-400">
          {SOURCE_NOTE}
        </p>
      </div>
    </div>
  );
}

